const GET = async (req, res) => {
    try {
        const { available, sort, page: pageParam, count: countParam, categories: categoriesParam } = req.query;
        // Parse and validate query parameters
        const filter = {
            available: parseBoolean(available),
            categoriesHandles: parseCategories(categoriesParam) // Updated to use handles instead of IDs
        };
        const display = {
            page: parseNumber(pageParam, 1),
            count: parseNumber(countParam, 20) // Added a more reasonable default
        };
        const sorting = {
            type: parseSortType(sort)
        };
        // Get service and fetch data
        const extenderService = req.scope.resolve("extenderService");
        const { data, metadata } = await extenderService.paginateWithMetadata(filter, sorting, display);
        // Return response
        res.status(200).json({
            products: data,
            metadata: {
                ...metadata,
                page: display.page,
                count: display.count
            }
        });
    }
    catch (error) {
        // Proper error handling
        console.error('Products route error:', error);
        res.status(500).json({
            message: 'An error occurred while fetching products',
            error: process.env.NODE_ENV === 'development' ? error.message : undefined
        });
    }
};

